-- gear rows that existed only in production.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local  apps/character-creator/db/restore-gear-missing-from-repo.sql
--   node scripts/d1-apply.mjs --remote apps/character-creator/db/restore-gear-missing-from-repo.sql
--
-- WHY THESE WERE MISSING. The catalog editor and the importer's confirm step
-- both write straight to D1. Nothing in git creates what they add, so a
-- database built from schema.sql plus the data scripts came up 58 gear
-- rows short, and every class citing one had a dead reference.
--
-- Found by a regression test, not by inspection: an audit of every only/except
-- restriction failed against a fresh build because it named skills that build
-- did not have. The same gap had already been found once for classes
-- (chiang-ku-dragon and juicer) and closed the same way.
--
-- NAMED restore-* DELIBERATELY. Data scripts are applied in filename order, and
-- an add-* file would sort BEFORE rename-skills-to-rue.sql: the restore would
-- insert Mathematics: Basic, the rename would then find its target name already
-- taken and skip, and a fresh build would end up holding BOTH that and the
-- Basic Math the seed created. restore-* sorts after rename-* and before
-- retire-*, so the renames happen first and this fills whatever is still short.
--
-- Exported from the live rows as they stand. Guarded on the key, so on
-- production this finds everything already present and does nothing - it is a
-- fresh environment that needs it.

INSERT OR IGNORE INTO gear
  (slug, name, system, category, description, source_book)
VALUES
  ('bio-comp-system', 'Bio Comp System', 'rifts', NULL, 'A Bio-Comp Monitor: a portable computer and sensor system clipped to the ears or fingers, measuring and recording blood pressure, temperature, heartbeat, respiration, hydration and a number of chemical responses detectable through the skin. Warns of dangerous or irregular signs.', 'Rifts Ultimate Edition p.261-265'),
  ('drug-injection-harness', 'Drug Injection Harness', 'rifts', NULL, 'STUB ' || char(8212) || ' created by class import, needs stats', 'rifts-core'),
  ('juicer-flex-plate-armor', 'Juicer Flex Plate Armor', 'rifts', NULL, 'STUB ' || char(8212) || ' created by class import, needs stats', 'rifts-core'),
  ('optic-helmet', 'Optic Helmet', 'rifts', NULL, 'A Multi-Optics Helmet (M.O.H.), an optical enhancement system built into a protective helmet: targeting sight and infrared optics to 1,600 feet, a telescopic monocular lens to 2 miles, and a thermal-imager to 1,600 feet that sees in darkness, shadow and through smoke. GIVES +1 TO STRIKE while the optics and targeting sight are engaged. Typically 2,800 to 3,400 credits.', 'Rifts Ultimate Edition p.261-265'),
  ('portable-irmss-kit', 'Portable Irmss Kit', 'rifts', NULL, 'An I.R.M.S.S. - Internal Robot Medical Surgeon System. Injects a dozen microscopic robots into the bloodstream to repair internal injury: blood clots, torn veins, internal bleeding and minor organ damage, equal to a surgical skill of 75%. Each kit holds 48 surgical robots, good for four uses; the robots are not reusable and flush from the body after about an hour.', 'Rifts Ultimate Edition p.261-265'),
  ('grey-fatigues', 'Grey Fatigues', 'rifts', NULL, 'Grey military fatigues.', 'Estimate - no published price found'),
  ('boots-with-knife-holster', 'Boots With Knife Holster', 'rifts', NULL, 'Boots with an integral sheath for a knife.', 'Estimate - no published price found'),
  ('gloves', 'Gloves', 'rifts', NULL, 'A plain pair of gloves.', 'Estimate - no published price found'),
  ('utility-belt', 'Utility Belt', 'rifts', NULL, 'A military-style utility belt, 3 to 5 credits.', 'Rifts Ultimate Edition p.261-265'),
  ('sunglasses', 'Sunglasses', 'rifts', NULL, 'Shaded lenses in various colours and strengths, against glare and bright light. Sturdy enough to take 8 S.D.C. Anywhere from 15 to 300 credits depending on make.', 'Web reference (not book-verified)'),
  ('canteen', 'Canteen', 'rifts', NULL, 'Plastic canteen holding 1 litre. An aluminium one runs about 30 credits, and a hard insulated one more again.', 'Web reference (not book-verified)'),
  ('compass', 'Compass', 'rifts', NULL, 'Typically 50 to 150 credits.', 'Rifts Ultimate Edition p.261-265'),
  ('e-clip', 'E Clip', 'rifts', NULL, 'Standard energy clip. 5,000 credits new and fully charged; about 3,500 for an old charged clip and 1,500 for an old empty one. Recharging costs around 1,500 credits and takes 1D4 hours at a proper station, or 1D12 hours on scavenged equipment.', 'Web reference (not book-verified)'),
  ('a-t-v-speedster-hover-cycle', 'A.T.V. Speedster Hover Cycle', 'rifts', 'vehicle', 'A fast all terrain hover vehicle common throughout the land. Vehicle Type: Hover cycle. Crew: One rider, one passenger is possible, but not comfortable on long trips. Engine: Combustion or electric engine. 98,000 credits gasoline engine or 110,000 credits for electric, or 450,000 nuclear with a 10 year life. Add 4000 for machinegun and 11,000 for laser. Weapons: Laser: 1D6 M.D., range is 1200 feet (366 m), payload is 20 shots. Or machinegun: 1D4 M.D. per burst of 50 rounds, range: 2000 feet (610 m), payload is 600 rounds (12 bursts). Mini-missile launchers can be added to the sides, firing two mini-missiles each, costing 55,000 credits for the pair.', 'Rifts Ultimate Edition'),
  ('binoculars', 'Binoculars', 'rifts', NULL, 'Hand-held magnifying optics, effective to about 1 mile. Typically 400 to 700 credits.', 'Web reference (not book-verified)'),
  ('boom-gun-glitter-boy-rail-gun', 'Boom Gun (Glitter Boy Rail Gun)', 'rifts', 'weapon', 'The Glitter Boy''s primary weapon, stabilized by an automatic system of jet thrusters and retractable reinforcement pylons that engage the moment the gun is fired. Primary Purpose: Assault and Anti-Armor. Secondary Purpose: Anti-Aircraft. Firing produces a sonic boom that temporarily deafens nearby characters and can shatter S.D.C. windows within 300 feet.', 'Rifts Ultimate Edition'),
  ('c-40r-coalition-samas-rail-gun', 'C-40R Coalition SAMAS Rail Gun', 'rifts', 'weapon', 'The SAMAS rail gun is listed here because it has been widely duplicated (the CS is not pleased by this) and is light enough to be used as a vehicle mounted or tripod mounted machinegun. Rarely available.', 'Rifts Ultimate Edition'),
  ('dog-pack-spiked-gloves', 'Dog Pack Spiked Gloves', 'rifts', 'weapon', 'Weighted, sap gloves that are part of the Dog Pack''s spiked image gimmick.', 'Rifts Ultimate Edition'),
  ('dog-pack-spiked-kneepads', 'Dog Pack Spiked Kneepads', 'rifts', 'weapon', 'Kneepads that have the weight and power of the legs behind them, part of the Dog Pack''s spiked image.', 'Rifts Ultimate Edition'),
  ('dog-pack-spikes-collars-arm-wrist-bands-other', 'Dog Pack Spikes (collars, arm/wrist bands, other)', 'rifts', 'weapon', 'Spiked collars, arm and wrist bands and other spiked gear; largely a stylistic gimmick to evoke fear and power. Hand and arm spikes can also be used to parry normal S.D.C. attacks; +1 bonus when parrying with spiked arm bands or glove only.', 'Rifts Ultimate Edition'),
  ('hooded-cloak', 'Hooded Cloak', 'rifts', NULL, 'A cloak with a hood.', 'Estimate - no published price found'),
  ('ja-11-juicer-assassin-s-energy-rifle', 'JA-11 Juicer Assassin''s Energy Rifle', 'rifts', 'weapon', 'The Juicer Assassin''s rifle is a Pre-Rifts design of remarkable ingenuity. The weapon can fire a single, hand loaded 7.62mm round for S.D.C. damage, fire a high intensity laser beam, or switch to an ion beam. The weapon also has a built-in laser targeting system and comes standard with a telescopic (2 mile/3.2 km) and infrared scope. Has a canister energy cell similar to CS canister E-Clips; laser targeting bonus +1 on an aimed shot.', 'Rifts Ultimate Edition'),
  ('ja-9-juicer-assassin-variable-laser-rifle', 'JA-9 Juicer Assassin Variable Laser Rifle', 'rifts', 'weapon', 'Another German Pre-Rifts design for the Juicer. A variable light frequency laser to overcome the laser resistant armors, like that of the Glitter Boy power armor. Greatly resembles the JA-11, complete with laser targeting and scope. Laser targeting bonus +1 to strike on an aimed shot.', 'Rifts Ultimate Edition'),
  ('knapsack', 'Knapsack', 'rifts', NULL, 'A knapsack, 50 to 100 credits.', 'Rifts Ultimate Edition p.261-265'),
  ('l-20-pulse-rifle', 'L-20 Pulse Rifle', 'rifts', 'weapon', 'A common frontier weapon manufactured by the black market and several kingdoms across the land. It is a dependable, lightweight weapon with the added feature of multiple laser bursts.', 'Rifts Ultimate Edition'),
  ('large-sack', 'Large Sack', 'rifts', NULL, 'A cheap carrying bag of hessian or synthetic fibre, around 36 inches long, holding up to about 99 lbs. Typically 2 to 6 credits.', 'Web reference (not book-verified)'),
  ('modified-ng-101-rail-gun-and-mini-missile-launchers', 'Modified NG-101 Rail Gun and Mini-Missile Launchers', 'rifts', 'weapon', 'A rail gun and mini-missile launcher is mounted on each of the sides of the NG-Sky King, near the midsection, above the concealed landing gear. Each contains a total of six mini-missiles. Primary Purpose: Anti-Personnel. Secondary Purpose: Anti-Armor (tanks, robots, dragons, etc).', 'Rifts Ultimate Edition'),
  ('musical-instrument', 'Musical Instrument', 'rifts', NULL, 'STUB ' || char(8212) || ' created by class import, needs stats', 'rifts-core'),
  ('neural-mace', 'Neural Mace', 'rifts', 'weapon', 'A hand-held weapon used by the Dog Pack; a stun weapon that releases an energy charge that temporarily short-circuits the nervous system. Penalties: -8 to strike, parry, and dodge for 2D4 melees; duration increased 2D4 melees per hit. Save vs Neural Mace is the same as saving against non-lethal poison, 16 or higher. Ineffective against environmental M.D.C. body and power armor, but effective against Dog Pack armor and half suits, or body armor without a helmet. The mace is a M.D.C. structure and can be used to parry M.D. attacks from robots and power armor.', 'Rifts Ultimate Edition'),
  ('ng-101-forward-mounted-heavy-laser', 'NG-101 Forward Mounted Heavy Laser', 'rifts', 'weapon', 'A heavy laser is mounted in the nose of the jet hover vehicle. It is fixed forward and can only shoot straight ahead. Primary Purpose: Anti-Personnel. Secondary Purpose: Defense.', 'Rifts Ultimate Edition'),
  ('ng-101-rail-gun', 'NG-101 Rail Gun', 'rifts', 'weapon', 'Not often available.', 'Rifts Ultimate Edition'),
  ('ng-202-rail-gun', 'NG-202 Rail Gun', 'rifts', 'weapon', 'Not always available.', 'Rifts Ultimate Edition'),
  ('ng-33-northern-gun-laser-pistol', 'NG-33 Northern Gun Laser Pistol', 'rifts', 'weapon', 'Looks like a sleeker ion blaster with a pointed nose.', 'Rifts Ultimate Edition'),
  ('ng-57-northern-gun-heavy-duty-ion-blaster', 'NG-57 Northern Gun Heavy-Duty Ion Blaster', 'rifts', 'weapon', 'A sturdy pistol from Northern Gun of the northern Michigan peninsula that packs a wallop but is comparatively heavy. A variety of scopes can be attached; illustration shows a standard telescopic sight for pistol or rifle.', 'Rifts Ultimate Edition'),
  ('ng-l5-northern-gun-laser-rifle', 'NG-L5 Northern Gun Laser Rifle', 'rifts', 'weapon', 'A durable, heavy-duty laser rifle that suffers from the usual problem of weight, but can endure a massive amount of abuse and keep on working.', 'Rifts Ultimate Edition'),
  ('ng-p7-northern-gun-particle-beam-rifle', 'NG-P7 Northern Gun Particle Beam Rifle', 'rifts', 'weapon', 'Another heavy-duty weapon that is a bit heavy and awkward, but sturdy and dependable in combat.', 'Rifts Ultimate Edition'),
  ('ng-super-laser-pistol-and-grenade-launcher', 'NG-Super Laser Pistol and Grenade Launcher', 'rifts', 'weapon', 'A dynamic short range weapon with the dual functions of laser gun and grenade launcher, twice the size of the C-18 laser pistol and three times as heavy. Characters with a strength of 19 or less are -3 to strike firing one handed, and -1 to strike when bracing it with both hands. Popular among bionically augmented headhunters, juicers, crazies, and those unusually strong.', 'Rifts Ultimate Edition'),
  ('northern-gun-sky-king', 'Northern Gun Sky King', 'rifts', 'vehicle', 'The most famous and popular combat vehicle created by the kingdom of Ishpeming (aka "The Northern Gun") is the heavy assault hover vehicle called the Sky King. The vehicle is fast, tough and reliable. Most importantly, it is brimming with weapons. Model Type: NG-A70. Class: All-Purpose Air Combat Vehicle. Crew: One. Note: The pilot is shielded and a small and difficult target to hit. Thus, he can only be hit when a character makes a called shot and even then the attacker is -3 to strike. Depleting the M.D.C. of the main body will destroy the Sky King. Driving on the ground: Not possible. Flying: The rocket propulsion system enables the Sky King to hover stationary up to 1000 feet (305 m) or fly. Maximum flying speed is 570 mph (912 km), but cruising speed is considered to range between 100 and 200 mph (160 and 320 km). Maximum altitude is limited to about 10,000 feet (3048 m). Flying Range: The nuclear power gives the NG-Sky King decades of life, but the jet rockets get hot and need to cool after a maximum of twenty hours of flight when travelling at speeds above cruising, and 48 hours with rest stops and/or at cruising speeds. Height: 17 feet (5 m). Width: 5 feet, 6 inches (1.7 m). Length: 11 feet, 5 inches (3.5 m). Weight: 2600 pounds (1170 kg) fully loaded. Cargo: Minimal storage space; about four feet (1.2m) behind seats for extra clothing, weapons, and personal items. Power System: Nuclear; average sky kings energy life is 12 years. Black Market Cost: 1.5 million credits, and up, for a new, undamaged, fully powered NG-Sky King complete with laser, mini-missiles, and rail guns. About a half million for a rebuilt cycle without weapon systems. Fair availability. Sensor System: Has all the standard robot sensors and communications capabilities, including radar. Special Bonuses: +2 to dodge when flying at cruising speeds and +5 to dodge when flying over 350 mph.', 'Rifts Ultimate Edition'),
  ('small-sack', 'Small Sack', 'rifts', NULL, 'A cheap carrying bag of hessian or synthetic fibre. Typically 2 to 6 credits. The source gives one set of figures for sacks rather than separate small and large ones.', 'Web reference (not book-verified)'),
  ('survival-knife', 'Survival Knife', 'rifts', NULL, 'A survival knife doing 1D6 S.D.C. Typically 120 to 300 credits.', 'Rifts Ultimate Edition p.261-265'),
  ('the-big-boss-a-t-v', 'The Big Boss A.T.V.', 'rifts', 'vehicle', 'A popular all terrain vehicle with good speed and good fuel milage. Vehicle Type: ATV Dune Buggy Type. Crew: One pilot and can accommodate three passengers comfortably. Maximum Speed: 150 mph (240 km). Engine: Combustion or electric engine. Maximum Range: 300 miles (480 km). Length: 16 feet (4.8 m). Weight: One ton. M.D.C. by Location: Tires (4) - 5 each, Main Body - 65. Black Market Cost: 24,000 credits gasoline engine or 28,000 credits for electric. Often comes with a sun roof and standard laser rifle attached to the roof; 360 degree rotation and 90 degree arc of fire. Add cost of rifle to vehicle.', 'Rifts Ultimate Edition'),
  ('the-highway-man-motorcycle', 'The Highway-Man Motorcycle', 'rifts', 'vehicle', 'A fast, rugged vehicle common to the city and flat lands. Comes standard with a laser or heavy machine gun. Vehicle Type: Motorcycle. Crew: One rider. Maximum Speed: 180 mph (288 km). Engine: Combustion or electric engine. Maximum Range: 400 miles (480 km). Length: 6 feet (1.8 m). Weight: 240 lbs (108 kg). M.D.C. by Location: Tires (2) - 1 each, Main Body ' || char(8212) || ' 75. Black Market Cost: 24,000 credits gasoline engine or 29,000 credits for electric. Add 6500 for machinegun and 12,000 for laser.', 'Rifts Ultimate Edition'),
  ('the-mountaineer-a-t-v', 'The Mountaineer A.T.V.', 'rifts', 'vehicle', 'An extremely popular armored, all terrain vehicle. It has a pilot''s compartment that can seat five and a large, enclosed cargo bay (10x8x8 foot cargo area). Vehicle Type: Three wheeled armored ATV transport vehicle. Crew: One pilot and can accommodate four passengers comfortably, plus cargo area. Maximum Speed: 120 mph (192 km). Engine: Combustion or electric engine or nuclear. Maximum Range: 600 miles (480 km), has an extra large tank or batteries. Length: 25 feet (7.6 m). Height: 18 feet (5.4 m). Weight: 6 tons. M.D.C. by Location: Super Tires (3) ' || char(8212) || ' 25 each, Main Body ' || char(8212) || ' 140, Reinforced Pilot''s Compartment ' || char(8212) || ' 50. Black Market Cost: 64,000 credits for basic vehicle (gasoline engine). Other features such as radar, radio, rail gun, etc. cost separately. 70,000 credits for electric engine and 500,000 for nuclear with a 20 year life. Additional armor can also be added at a cost of 10,000 credits per 30 M.D.C.', 'Rifts Ultimate Edition'),
  ('the-wastelander-motorcycle', 'The Wastelander Motorcycle', 'rifts', 'vehicle', 'A heavy duty rough terrain vehicle with a large storage area built into the back end. Vehicle Type: Motorcycle. Crew: One rider. Maximum Speed: 120 mph (192 km). Engine: Combustion or electric engine. Maximum Range: 400 miles (480 km). Length: 9 feet (2.7 m). Weight: 800 lbs (360 kg). M.D.C. by Location: Tires (2) ' || char(8212) || ' 1 each, Main Body ' || char(8212) || ' 45. Black Market Cost: 18,000 credits gasoline engine or 21,000 credits for electric. Add 4000 for machinegun and 11,000 for laser.', 'Rifts Ultimate Edition'),
  ('traveling-clothes', 'Traveling Clothes', 'rifts', NULL, 'Hard-wearing clothing for the road.', 'Estimate - no published price found'),
  ('vibro-claws', 'Vibro-Claws', 'rifts', 'weapon', 'Usually three hooked blades attached to a forearm gauntlet or protective plate. Great for parrying and slashing. Falls into the W.P. Knife category.', 'Rifts Ultimate Edition'),
  ('vibro-knife', 'Vibro-Knife', 'rifts', 'weapon', 'A blade weapon surrounded by an invisible high-frequency energy field that gives it mega-damage capabilities.', 'Rifts Ultimate Edition'),
  ('vibro-saber', 'Vibro-Saber', 'rifts', 'weapon', 'Short sword; a blade weapon surrounded by an invisible high-frequency energy field that gives it mega-damage capabilities.', 'Rifts Ultimate Edition'),
  ('vibro-sword', 'Vibro-Sword', 'rifts', 'weapon', 'Larger, one-handed sword; a blade weapon surrounded by an invisible high-frequency energy field that gives it mega-damage capabilities.', 'Rifts Ultimate Edition'),
  ('wilk-s-320-laser-pistol', 'Wilk''s 320 Laser Pistol', 'rifts', 'weapon', 'An excellent laser pistol known for its durability, range, accuracy and light weight; sleek, black plastic and ceramic weapon popular among mercenaries and adventurers. +2 bonus to strike on an aimed shot because of the light weight and superior balance.', 'Rifts Ultimate Edition'),
  ('wilk-s-447-laser-rifle', 'Wilk''s 447 Laser Rifle', 'rifts', 'weapon', 'A rifle version of the Wilk''s handgun with all the usual features of a Wilk''s product. +1 to strike on an aimed shot.', 'Rifts Ultimate Edition'),
  ('wilk-s-jet-pack', 'Wilk''s Jet Pack', 'rifts', 'vehicle', 'A small personal jet pack capable of sustained flight. The Wilk''s jet pack comes as a back pack like harness equipped with helmet, neck support, short range radio, and compass. Vehicle Type: Jet Pack. Crew: One rider. Maximum Speed: 120 mph (192 km). Engine: Combustion or electric engine or nuclear. Maximum Range: 800 miles (1280 km). Length: 3 feet (0.9 m). Black Market Cost: 38,000 credits gasoline engine or 50,000 credits for electric, or 350,000 nuclear with a 10 year life. Weapons: None built into the pack, but normal hand guns and rifles can be used in flight.', 'Rifts Ultimate Edition'),
  ('wilk-s-laser-scalpel', 'Wilk''s Laser Scalpel', 'rifts', 'gear', 'A laser tool designed for delicate surgery with several settings for very fine damage. Not meant to be used as a weapon.', 'Rifts Ultimate Edition'),
  ('wilk-s-laser-wand-tool', 'Wilk''s Laser Wand (tool)', 'rifts', 'gear', 'A small pen or pocket flashlight sized item, about 6 inches long, designed for detail laser work on electronics. Designed for close work, one to three feet, and not meant to be a weapon. Mini-Energy Clip costs 200 credits.', 'Rifts Ultimate Edition'),
  ('wilk-s-portable-laser-torch-tool', 'Wilk''s Portable Laser Torch (tool)', 'rifts', 'gear', 'A wonderful tool for cutting and welding, made of the familiar Wilk''s black, lightweight plastic and ceramic construction. A power cord connects the gun to its portable power pack, charged by two standard weapon E-clips. Designed to be a tool, not a weapon; can slice through a 600 S.D.C. metal door in 15 seconds on the 1D6 M.D. setting.', 'Rifts Ultimate Edition'),
  ('cyber-armor', 'Cyber Armor', 'rifts', 'armor', 'Cyber-Knight cyber-armor, grown rather than worn. A.R. 16, rising to 17 at level 8. M.D.C. by location at level 1: chest plate 50, back shoulder blades 15 each, thigh/upper leg 15 each, forearms 10 each, shoulders 8 each. From level 4 it becomes a living part of the knight: it regenerates 1D6 M.D.C. per hour, the chest plate gains 1D6 M.D.C. per level and every other location gains 1.', 'Web reference (not book-verified)'),
  ('leather-armor', 'Leather Armor', 'palladium-fantasy', 'armor', 'STUB ' || char(8212) || ' referenced by a class, needs stats', NULL),
  ('huntsman-armor', 'Huntsman Armor', 'rifts', NULL, 'STUB ' || char(8212) || ' created by class import, needs stats', 'Rifts Book of Magic');

-- Read the result back rather than trusting the exit code.
SELECT count(*) AS gear_total FROM gear;

INSERT INTO data_script_runs (filename) VALUES ('restore-gear-missing-from-repo.sql');
